'use strict';

var utils = require('./utils-Dza9QMmG.cjs');

const filesMiddleware = async (context, next) => {
  if (context.params && utils.isMediaUpload(context.method, context.params)) {
    const [formData, rest] = await utils.extractFilesToFormData(
      context.method,
      context.params
    );
    if (formData) context.formData = formData;
    context.params = rest;
  }
  return next();
};

exports.filesMiddleware = filesMiddleware;
